@Component
@RequiredArgsConstructor
public class ReporteAuditoriaTasklet implements Tasklet {

    private final CuentaDescuadradaRepository descuadres;
    private final ReporteJasper reporte;              // AUDSDOSCTD, 132 columnas
    private final MessageChannel bandejaOrquestador;  // Spring Integration: sustituye BANDERACTD
    private final SaldoAccRepository saldos;

    @Override
    public RepeatStatus execute(StepContribution sc, ChunkContext ctx) {
        long ejecucion = ctx.getStepContext().getStepExecution().getJobExecutionId();
        List<CuentaDescuadrada> lista = descuadres.findByEjecucionOrderByCuenta(ejecucion);
        if (lista.isEmpty()) {
            reporte.sinInformacion("001AUDSDOSCTD");                  // "NO HUBO INFORMACION"
        } else {
            reporte.genera("001AUDSDOSCTD", lista);                   // diferencia + movimientos
        }
        bandejaOrquestador.send(MessageBuilder.withPayload("BANDE-171")  // REG-ARCH-171
                .setHeader("fechaProceso", ctx.getStepContext().getJobParameters().get("fechaProceso"))
                .build());
        descuadres.purga(ejecucion);                                  // CLOSE ARCH-CTAS2 WITH PURGE
        saldos.purga(ejecucion);
        return RepeatStatus.FINISHED;
    }
}
